def max_sum(arr):
    n = len(arr)
    # Initialize two arrays to store the maximum sum of increasing and decreasing subsequences
    inc = [arr[i] for i in range(n)]
    dec = [arr[i] for i in range(n)]

    # Fill the inc array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill the dec array
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find the maximum sum of a bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

