def validate(n):
    # Convert the number to a string to iterate over each digit
    s = str(n)
    # Create a dictionary to count the frequency of each digit
    d = {}
    for i in s:
        if i in d:
            d[i] += 1
        else:
            d[i] = 1
    # Check if the frequency of each digit is less than or equal to the digit itself
    for i in d:
        if int(i) < d[i]:
            return False
    return True
