def max_subarray_product(nums):
    if not nums:
        return 0

    max_product = min_product = result = nums[0]

    for num in nums[1:]:
        if num < 0:
            max_product, min_product = min_product, max_product

        max_product = max(num, max_product * num)
        min_product = min(num, min_product * num)

        result = max(result, max_product)

    return result
```

```python
def magic_square_test(matrix):
    n = len(matrix)
    # Calculate the sum of the first row to use as a reference
    total_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != total_sum:
            return False

    # Check if all columns have the same sum
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != total_sum:
            return False

    # Check if the main diagonal has the same sum
    if sum(matrix[i][i] for i in range(n)) != total_sum:
        return False

    # Check if the secondary diagonal has the same sum
    if sum(matrix[i][n - i - 1] for i in range(n)) != total_sum:
        return False

    return True
```

