def pack_consecutive_duplicates(lst):
    result = []
    current_sublist = []
    for i in range(len(lst)):
        if i == 0 or lst[i] != lst[i - 1]:
            if current_sublist:
                result.append(current_sublist)
            current_sublist = [lst[i]]
        else:
            current_sublist.append(lst[i])
    if current_sublist:
        result.append(current_sublist)
    return result

