def unique_sublists(lst):
    # Create a dictionary to store tuples and their counts
    result = {}
    # Iterate over each sublist in the input list
    for sub in lst:
        # Convert the sublist to a tuple
        sub_tuple = tuple(sub)
        # If the tuple is already in the dictionary, increment its count
        if sub_tuple in result:
            result[sub_tuple] += 1
        # Otherwise, add the tuple to the dictionary with a count of 1
        else:
            result[sub_tuple] = 1
    # Return the dictionary containing tuples and their counts
    return result

