def max_product(nums):
    n = len(nums)
    dp = [nums[i] for i in range(n)]

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)

