def find_sum(lst):
    # Create a dictionary to count occurrences of each element
    count_dict = {}
    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Calculate the sum of elements that appear only once
    result = sum(num for num, count in count_dict.items() if count == 1)
    return result

# Test the function with the provided test case
assert find_sum([1, 2, 3, 1, 1, 4, 5, 6]) == 21
